def _load_embedded():
    """Decompress and load embedded mapping data."""
    compressed = base64.b64decode(_EMBEDDED_DATA)
    json_str = zlib.decompress(compressed).decode('utf-8')
    return json.loads(json_str)

# ============================================================
# Configuration
# ============================================================
ALLOWED_CHARS = set()
ALLOWED_CHARS.update("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
ALLOWED_CHARS.update("abcdefghijklmnopqrstuvwxyz")
ALLOWED_CHARS.update("0123456789")
ALLOWED_CHARS.update(".,!?:;'\"-")
ALLOWED_CHARS.update("\u2014")  # em dash
ALLOWED_CHARS.update("\u2026")  # ellipsis
ALLOWED_CHARS.update("()[]{}")
ALLOWED_CHARS.update("/\\_")
ALLOWED_CHARS.update(" ")       # space

# ============================================================
# Auto-normalization: typographic -> ASCII equivalents
# ============================================================
NORMALIZE_MAP = {
    "\u2018": "'", "\u2019": "'", "\u201A": "'", "\u201B": "'",
    "\u201C": '"', "\u201D": '"', "\u201E": '"', "\u201F": '"',
    "\uFF07": "'", "\uFF02": '"',
    "\u2010": "-", "\u2011": "-", "\u2012": "-", "\u2013": "-",
    "\uFF0C": ",", "\uFF0E": ".", "\uFF01": "!", "\uFF1F": "?",
    "\uFF1A": ":", "\uFF1B": ";",
    "\uFF08": "(", "\uFF09": ")",
    "\uFF3B": "[", "\uFF3D": "]",
    "\uFF5B": "{", "\uFF5D": "}",
    "\uFF0F": "/", "\uFF3C": "\\", "\uFF3F": "_",
    "\u3000": " ",
    "\uFF10": "0", "\uFF11": "1", "\uFF12": "2",
    "\uFF13": "3", "\uFF14": "4", "\uFF15": "5",
    "\uFF16": "6", "\uFF17": "7", "\uFF18": "8",
    "\uFF19": "9",
}

def normalize_text(text):
    return text.translate(str.maketrans(NORMALIZE_MAP))

# ============================================================
# Terminal colors (Windows-compatible)
# ============================================================
class C:
    BOLD    = ""
    DIM     = ""
    RED     = ""
    GREEN   = ""
    YELLOW  = ""
    BLUE    = ""
    MAGENTA = ""
    CYAN    = ""
    RESET   = ""

def enable_colors():
    """Enable ANSI colors on Windows 10+."""
    global C
    if sys.platform == "win32":
        try:
            import ctypes
            kernel32 = ctypes.windll.kernel32
            kernel32.SetConsoleMode(kernel32.GetStdHandle(-11), 7)
        except Exception:
            pass
    C.BOLD    = "\033[1m"
    C.DIM     = "\033[2m"
    C.RED     = "\033[91m"
    C.GREEN   = "\033[92m"
    C.YELLOW  = "\033[93m"
    C.BLUE    = "\033[94m"
    C.MAGENTA = "\033[95m"
    C.CYAN    = "\033[96m"
    C.RESET   = "\033[0m"

# ============================================================
# Load mapping
# ============================================================
_data = _load_embedded()
mapping = _data["mapping"]
noise_list = _data["noise"]

reverse_mapping = {}
for _char, _cps in mapping.items():
    for _cp in _cps:
        reverse_mapping[_cp] = _char

noise_chars = [chr(int(cp[2:], 16)) for cp in noise_list]

# ============================================================
# Core functions
# ============================================================
def cp_to_char(cp_str):
    return chr(int(cp_str[2:], 16))

def validate_input(text):
    invalid = []
    for ch in text:
        if ch not in ALLOWED_CHARS:
            invalid.append(ch)
    return (len(invalid) == 0, invalid)

def obfuscate(text, noise_min=10, noise_max=30, noise_ratio_min=0.15, noise_ratio_max=0.40):
    text = normalize_text(text)
    valid, invalid = validate_input(text)
    if not valid:
        raise ValueError(invalid)
    encoded_chars = []
    for ch in text:
        group = mapping[ch]
        selected = random.choice(group)
        encoded_chars.append(cp_to_char(selected))
    text_len = len(text)
    ratio_count = int(text_len * random.uniform(noise_ratio_min, noise_ratio_max))
    noise_count = max(noise_min, min(noise_max, ratio_count))
    noise_count = max(noise_count, noise_min)
    result = list(encoded_chars)
    noise_to_insert = [random.choice(noise_chars) for _ in range(noise_count)]
    for nc in noise_to_insert:
        pos = random.randint(0, len(result))
        result.insert(pos, nc)
    return ''.join(result), noise_count

def deobfuscate(text):
    result = []
    noise_removed = 0
    for ch in text:
        cp_str = f"U+{ord(ch):05X}"
        if cp_str in reverse_mapping:
            result.append(reverse_mapping[cp_str])
        else:
            noise_removed += 1
    return ''.join(result), noise_removed

# ============================================================
# Clipboard helper (Windows / macOS / Linux)
# ============================================================
def copy_to_clipboard(text):
    if sys.platform == "win32":
        try:
            process = subprocess.Popen(['clip'], stdin=subprocess.PIPE, shell=True)
            process.communicate(text.encode('utf-8'))
            return True
        except Exception:
            return False
    else:
        try:
            process = subprocess.Popen(['pbcopy'], stdin=subprocess.PIPE)
            process.communicate(text.encode('utf-8'))
            return True
        except (FileNotFoundError, Exception):
            try:
                process = subprocess.Popen(['xclip', '-selection', 'clipboard'], stdin=subprocess.PIPE)
                process.communicate(text.encode('utf-8'))
                return True
            except (FileNotFoundError, Exception):
                return False

def paste_from_clipboard():
    if sys.platform == "win32":
        try:
            result = subprocess.run(
                ['powershell', '-command', 'Get-Clipboard'],
                capture_output=True, text=True, encoding='utf-8'
            )
            return result.stdout
        except Exception:
            return ""
    else:
        try:
            result = subprocess.run(['pbpaste'], capture_output=True, text=True)
            return result.stdout
        except (FileNotFoundError, Exception):
            try:
                result = subprocess.run(['xclip', '-selection', 'clipboard', '-o'],
                                        capture_output=True, text=True)
                return result.stdout
            except (FileNotFoundError, Exception):
                return ""

# ============================================================
# UI helpers
# ============================================================
def print_banner():
    print(f"{C.CYAN}{'='*56}{C.RESET}")
    print(f"{C.CYAN}  {C.BOLD}Unicode Obfuscation Engine  v2.0{C.RESET}")
    print(f"{C.CYAN}  CJK Extension B-J | 83 chars x 800 + 8032 noise{C.RESET}")
    print(f"{C.CYAN}{'='*56}{C.RESET}")

def print_divider():
    print(f"{C.DIM}{'-'*56}{C.RESET}")

def print_allowed():
    chars_display = (
        "A-Z a-z 0-9\n"
        "  . , ! ? : ; ' \" - \u2014 \u2026\n"
        "  ( ) [ ] { } / \\ _ [space]"
    )
    print(f"\n{C.DIM}Allowed characters:{C.RESET}")
    print(f"  {chars_display}")
    print(f"  {C.DIM}(smart quotes, fullwidth chars auto-converted){C.RESET}")

def format_invalid_msg(invalid_chars):
    unique = list(dict.fromkeys(invalid_chars))
    parts = []
    for ch in unique[:10]:
        parts.append(f"{C.RED}'{ch}'{C.RESET} {C.DIM}(U+{ord(ch):04X}){C.RESET}")
    msg = ", ".join(parts)
    if len(unique) > 10:
        msg += f" {C.DIM}... +{len(unique)-10} more{C.RESET}"
    return msg

def read_single_line(prompt):
    print(f"{C.GREEN}{prompt}{C.RESET}")
    print(f"{C.DIM}  (Paste text and press Enter){C.RESET}")
    try:
        line = input(f"{C.GREEN}> {C.RESET}")
        return line
    except (EOFError, KeyboardInterrupt):
        return ""

def read_multiline(prompt):
    print(f"{C.GREEN}{prompt}{C.RESET}")
    print(f"{C.DIM}  (Enter blank line or Ctrl+Z+Enter to finish){C.RESET}")
    lines = []
    while True:
        try:
            line = input()
        except EOFError:
            break
        if line == "" and lines:
            break
        if line == "" and not lines:
            continue
        lines.append(line)
    return '\n'.join(lines)

# ============================================================
# Interactive mode
# ============================================================
def interactive_encode():
    print(f"\n{C.BOLD}{C.GREEN}[ Encode ]{C.RESET}")
    print_allowed()
    print(f"\n  {C.BOLD}1{C.RESET}  Type or paste text")
    print(f"  {C.BOLD}2{C.RESET}  Read from file")
    print(f"  {C.BOLD}q{C.RESET}  Cancel")
    try:
        choice = input(f"\n{C.GREEN}Choice> {C.RESET}").strip().lower()
    except (EOFError, KeyboardInterrupt):
        return
    if choice == '1':
        text = read_multiline("\nType or paste your text:")
    elif choice == '2':
        filepath = input(f"{C.GREEN}File path: {C.RESET}").strip()
        if not filepath or not os.path.isfile(filepath):
            print(f"{C.YELLOW}  File not found.{C.RESET}")
            return
        with open(filepath, 'r', encoding='utf-8') as f:
            text = f.read().strip()
        print(f"  {C.GREEN}OK{C.RESET} Read {len(text)} chars from {filepath}")
    else:
        return
    if not text.strip():
        print(f"{C.YELLOW}  Empty input, cancelled.{C.RESET}")
        return
    text = normalize_text(text)
    valid, invalid = validate_input(text)
    if not valid:
        print(f"\n{C.RED}  X Invalid characters:{C.RESET} {format_invalid_msg(invalid)}")
        print(f"{C.YELLOW}  Please remove them and try again.{C.RESET}")
        return
    encoded, noise_count = obfuscate(text)
    orig_len = len(text)
    enc_len = len(encoded)
    print(f"\n{C.CYAN}{'-'*56}{C.RESET}")
    print(f"  {C.BOLD}Result:{C.RESET}\n")
    print(f"  {C.MAGENTA}{encoded}{C.RESET}")
    print(f"\n{C.DIM}  - Original length:  {orig_len} chars{C.RESET}")
    print(f"{C.DIM}  - Encoded length:   {enc_len} chars{C.RESET}")
    print(f"{C.DIM}  - Noise inserted:   {noise_count} chars{C.RESET}")
    print(f"{C.DIM}  - Expansion ratio:  {enc_len/orig_len:.1f}x{C.RESET}")
    if copy_to_clipboard(encoded):
        print(f"\n  {C.GREEN}> Copied to clipboard{C.RESET}")
    else:
        print(f"\n  {C.DIM}(clipboard not available){C.RESET}")

def interactive_decode():
    print(f"\n{C.BOLD}{C.GREEN}[ Decode ]{C.RESET}")
    print(f"{C.DIM}  Recover original text from obfuscated Unicode.{C.RESET}")
    clipboard_text = paste_from_clipboard().strip()
    if clipboard_text:
        has_cjk = any(0x20000 <= ord(ch) <= 0x3347F for ch in clipboard_text[:20])
        if has_cjk:
            preview = clipboard_text[:30] + "..." if len(clipboard_text) > 30 else clipboard_text
            print(f"\n  {C.DIM}Clipboard content ({len(clipboard_text)} chars):{C.RESET}")
            print(f"  {C.DIM}{preview}{C.RESET}")
            print(f"\n  {C.BOLD}1{C.RESET}  Decode from clipboard {C.GREEN}(recommended){C.RESET}")
            print(f"  {C.BOLD}2{C.RESET}  Decode from file")
            print(f"  {C.BOLD}3{C.RESET}  Type/paste manually")
            print(f"  {C.BOLD}q{C.RESET}  Cancel")
            try:
                choice = input(f"\n{C.GREEN}Choice> {C.RESET}").strip().lower()
            except (EOFError, KeyboardInterrupt):
                return
            if choice == '1':
                text = clipboard_text
            elif choice == '2':
                filepath = input(f"{C.GREEN}File path: {C.RESET}").strip()
                if not filepath or not os.path.isfile(filepath):
                    print(f"{C.YELLOW}  File not found.{C.RESET}")
                    return
                with open(filepath, 'r', encoding='utf-8') as f:
                    text = f.read().strip()
            elif choice == '3':
                text = read_single_line("\nPaste obfuscated text:")
            else:
                return
        else:
            print(f"\n  {C.BOLD}1{C.RESET}  Decode from file")
            print(f"  {C.BOLD}2{C.RESET}  Type/paste manually")
            print(f"  {C.BOLD}q{C.RESET}  Cancel")
            try:
                choice = input(f"\n{C.GREEN}Choice> {C.RESET}").strip().lower()
            except (EOFError, KeyboardInterrupt):
                return
            if choice == '1':
                filepath = input(f"{C.GREEN}File path: {C.RESET}").strip()
                if not filepath or not os.path.isfile(filepath):
                    print(f"{C.YELLOW}  File not found.{C.RESET}")
                    return
                with open(filepath, 'r', encoding='utf-8') as f:
                    text = f.read().strip()
            elif choice == '2':
                text = read_single_line("\nPaste obfuscated text:")
            else:
                return
    else:
        print(f"\n  {C.BOLD}1{C.RESET}  Decode from file")
        print(f"  {C.BOLD}2{C.RESET}  Type/paste manually")
        print(f"  {C.BOLD}q{C.RESET}  Cancel")
        try:
            choice = input(f"\n{C.GREEN}Choice> {C.RESET}").strip().lower()
        except (EOFError, KeyboardInterrupt):
            return
        if choice == '1':
            filepath = input(f"{C.GREEN}File path: {C.RESET}").strip()
            if not filepath or not os.path.isfile(filepath):
                print(f"{C.YELLOW}  File not found.{C.RESET}")
                return
            with open(filepath, 'r', encoding='utf-8') as f:
                text = f.read().strip()
        elif choice == '2':
            text = read_single_line("\nPaste obfuscated text:")
        else:
            return
    if not text.strip():
        print(f"{C.YELLOW}  Empty input, cancelled.{C.RESET}")
        return
    result, noise_removed = deobfuscate(text)
    print(f"\n{C.CYAN}{'-'*56}{C.RESET}")
    print(f"  {C.BOLD}Result:{C.RESET}\n")
    print(f"  {C.GREEN}{result}{C.RESET}")
    print(f"\n{C.DIM}  - Decoded length:   {len(result)} chars{C.RESET}")
    print(f"{C.DIM}  - Noise removed:    {noise_removed} chars{C.RESET}")
    if copy_to_clipboard(result):
        print(f"\n  {C.GREEN}> Copied to clipboard{C.RESET}")

def interactive_roundtrip():
    print(f"\n{C.BOLD}{C.GREEN}[ Round-trip Demo ]{C.RESET}")
    print(f"{C.DIM}  Encode then immediately decode to verify integrity.{C.RESET}")
    print_allowed()
    text = read_multiline("\nType your text:")
    if not text.strip():
        print(f"{C.YELLOW}  Empty input, cancelled.{C.RESET}")
        return
    text = normalize_text(text)
    valid, invalid = validate_input(text)
    if not valid:
        print(f"\n{C.RED}  X Invalid characters:{C.RESET} {format_invalid_msg(invalid)}")
        return
    encoded, noise_count = obfuscate(text)
    decoded, noise_removed = deobfuscate(encoded)
    match = "> Match" if decoded == text else "X MISMATCH"
    print(f"\n{C.CYAN}{'-'*56}{C.RESET}")
    print(f"  {C.DIM}Original:{C.RESET}  {text}")
    print(f"  {C.DIM}Encoded:{C.RESET}   {C.MAGENTA}{encoded}{C.RESET}")
    print(f"  {C.DIM}Decoded:{C.RESET}   {C.GREEN}{decoded}{C.RESET}")
    print(f"\n  {C.BOLD}{match}{C.RESET}  {C.DIM}| noise: {noise_count} in, {noise_removed} out{C.RESET}")

def interactive_loop():
    enable_colors()
    print_banner()
    while True:
        print(f"\n{C.CYAN}{'-'*56}{C.RESET}")
        print(f"  {C.BOLD}1{C.RESET}  Encode text")
        print(f"  {C.BOLD}2{C.RESET}  Decode text")
        print(f"  {C.BOLD}3{C.RESET}  Round-trip demo (encode -> decode)")
        print(f"  {C.BOLD}q{C.RESET}  Quit")
        try:
            choice = input(f"\n{C.GREEN}Choice> {C.RESET}").strip().lower()
        except (EOFError, KeyboardInterrupt):
            print(f"\n{C.DIM}Bye.{C.RESET}")
            break
        if choice == '1':
            interactive_encode()
        elif choice == '2':
            interactive_decode()
        elif choice == '3':
            interactive_roundtrip()
        elif choice == 'q':
            print(f"{C.DIM}Bye.{C.RESET}")
            break
        else:
            print(f"{C.YELLOW}  Unknown choice. Enter 1, 2, 3, or q.{C.RESET}")

# ============================================================
# CLI mode
# ============================================================
def cli_mode():
    import argparse
    parser = argparse.ArgumentParser(
        prog="obfuscate",
        description="Unicode Obfuscation Engine",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument("text", nargs="?", help="Text to encode/decode")
    parser.add_argument("-d", "--decode", action="store_true", help="Decode mode")
    parser.add_argument("-f", "--file", help="Read input from file")
    parser.add_argument("-o", "--output", help="Write result to file")
    parser.add_argument("--noise-min", type=int, default=10)
    parser.add_argument("--noise-max", type=int, default=30)
    parser.add_argument("--no-clipboard", action="store_true")
    parser.add_argument("--stats", action="store_true")
    args = parser.parse_args()

    if args.file:
        with open(args.file, 'r', encoding='utf-8') as f:
            input_text = f.read().rstrip('\n')
    elif args.text:
        input_text = args.text
    elif not sys.stdin.isatty():
        input_text = sys.stdin.read().rstrip('\n')
    else:
        interactive_loop()
        return

    if not input_text:
        return

    if args.decode:
        result, noise_count = deobfuscate(input_text)
        if args.output:
            with open(args.output, 'w', encoding='utf-8') as f:
                f.write(result + '\n')
        else:
            print(result)
    else:
        try:
            result, noise_count = obfuscate(input_text,
                                            noise_min=args.noise_min,
                                            noise_max=args.noise_max)
        except ValueError as invalid_chars:
            print(f"Invalid characters: {format_invalid_msg(invalid_chars.args[0])}", file=sys.stderr)
            sys.exit(1)
        if args.output:
            with open(args.output, 'w', encoding='utf-8') as f:
                f.write(result + '\n')
        else:
            print(result)
        if not args.no_clipboard:
            copy_to_clipboard(result)

if __name__ == "__main__":
    try:
        cli_mode()
    except KeyboardInterrupt:
        print(f"\nInterrupted.")
        sys.exit(0)
